import{_ as e,o as r,c as a,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"Video Understanding Basics","description":"","frontmatter":{"title":"Video Understanding Basics","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/video-understanding.md","filePath":"en/tutorials/video-understanding.md","lastUpdated":null}'),o={name:"en/tutorials/video-understanding.md"};function s(i,t,d,g,l,h){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="video-understanding-basics" tabindex="-1">Video Understanding Basics <a class="header-anchor" href="#video-understanding-basics" aria-label="Permalink to &quot;Video Understanding Basics&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/video-understanding">视频理解基础</a><strong>Coverage</strong>: June 2025 – August 2026, with earlier foundational work included only as background. <strong>Scale</strong>: 11 chapters (0–10) + 3 appendices, <strong>394 papers, every one of them explained individually</strong> in Chapter 10.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it states what the tutorial argues, reproduces the measurements it treats as load-bearing evidence, and gives the full chapter structure. Every derivation, table, diagram and per-paper entry lives in the <a href="/notes/tutorials/video-understanding">Chinese edition</a>.</p></div><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>Anyone who wants to go from &quot;I know what a ViT and an LLM are&quot; to &quot;I can read this year&#39;s video-understanding literature and tell which results are real.&quot; It covers principles → tasks → benchmarks → data → methods, in that order.</p><p>The ordering is deliberate. <strong>Benchmarks come before methods</strong>, because without knowing where the scores come from, reading method papers is reading advertisements.</p><h2 id="the-one-argument-this-tutorial-is-built-around" tabindex="-1">The one argument this tutorial is built around <a class="header-anchor" href="#the-one-argument-this-tutorial-is-built-around" aria-label="Permalink to &quot;The one argument this tutorial is built around&quot;">​</a></h2><p>The most important output of this field between mid-2025 and mid-2026 was not a model. It was a group of <strong>audit papers</strong> showing that a large share of &quot;video understanding&quot; scores does not come from the video.</p><p>Every number below is transcribed verbatim from the cited paper; none was reproduced by the author.</p><table tabindex="0"><thead><tr><th>Trivial baseline</th><th>Score</th><th>Source</th></tr></thead><tbody><tr><td>Share of items in existing benchmarks solvable with <strong>no visual input and no temporal context</strong></td><td><strong>55%</strong> (24,416 → 11,033 items retained)</td><td>Video-Oasis, <a href="https://arxiv.org/abs/2603.29616" target="_blank" rel="noreferrer">arXiv:2603.29616</a></td></tr><tr><td><strong>Single frame, no audio</strong> answering AVQA</td><td><strong>~76%</strong></td><td><a href="https://arxiv.org/abs/2509.17901" target="_blank" rel="noreferrer">arXiv:2509.17901</a></td></tr><tr><td><strong>Bag-of-words SigLIP</strong> (NoSense), discarding nearly all temporal structure, on VSI-Super-Recall</td><td><strong>98.3%</strong> at 10 min, <strong>~95%</strong> on 4-hour videos</td><td><a href="https://arxiv.org/abs/2511.16655" target="_blank" rel="noreferrer">arXiv:2511.16655</a></td></tr><tr><td><strong>Last-4-frames sliding window</strong> (SimpleStream) vs 13 published streaming models</td><td>OVO-Bench <strong>67.7%</strong>, StreamingBench <strong>80.59%</strong></td><td><a href="https://arxiv.org/abs/2604.02317" target="_blank" rel="noreferrer">arXiv:2604.02317</a></td></tr><tr><td>Differences among <strong>20 models under a black screen</strong></td><td><strong>not significant (p = 0.53)</strong>; on original video p = 0.0003</td><td><a href="https://arxiv.org/abs/2607.13305" target="_blank" rel="noreferrer">arXiv:2607.13305</a></td></tr><tr><td>Contribution of <strong>frame order</strong> across 16 open-weight models</td><td><strong>near zero</strong>; frame diversity supplies most of the visual benefit</td><td><a href="https://arxiv.org/abs/2607.13305" target="_blank" rel="noreferrer">arXiv:2607.13305</a></td></tr><tr><td><strong>Content-blind logistic regression</strong> (description length + generator identity) vs a LoRA-tuned 7B audio-visual judge</td><td><strong>65.8 vs 66.8 WAF</strong>, CIs fully overlapping</td><td><a href="https://arxiv.org/abs/2607.18508" target="_blank" rel="noreferrer">arXiv:2607.18508</a></td></tr><tr><td><strong>Linear probe on frozen self-supervised features</strong> vs purpose-built deepfake detectors</td><td>approaches them across video, image and audio</td><td><a href="https://arxiv.org/abs/2606.26384" target="_blank" rel="noreferrer">arXiv:2606.26384</a></td></tr></tbody></table><p>Two consequences the tutorial draws from this:</p><p><strong>Frame diversity, not frame order.</strong> Shuffling frames costs almost nothing. So a method that merely lets the model see more distinct frames should not claim to have improved temporal modelling.</p><p><strong>Even shuffle-sensitivity is not proof.</strong> A model can recover order from <strong>RoPE position indices</strong> rather than from pixels. Reversing the pixels while pinning RoPE forward separates the two channels: Molmo2 4B is unchanged (0.965 → 0.965) while Qwen3-VL 4B collapses (0.944 → 0.576), even though the two look identical under every conventional temporal audit (<a href="https://arxiv.org/abs/2607.12304" target="_blank" rel="noreferrer">arXiv:2607.12304</a>).</p><h2 id="other-load-bearing-measurements" tabindex="-1">Other load-bearing measurements <a class="header-anchor" href="#other-load-bearing-measurements" aria-label="Permalink to &quot;Other load-bearing measurements&quot;">​</a></h2><p><strong>At hour scale the binding constraint is search, not recognition.</strong> On 2,273 queries over 194 videos averaging 75.7 minutes, <strong>every open Video-LLM collapses while a frame-level retrieval baseline beats them</strong>; a failure taxonomy attributes <strong>85% of failures to search</strong>, and a retrieve-then-ground hybrid recovers <strong>6.7×</strong> (<a href="https://arxiv.org/abs/2606.12300" target="_blank" rel="noreferrer">arXiv:2606.12300</a>).</p><p><strong>Length is not difficulty; verifiability is.</strong> Benchmarks now reach month-scale (300+ hours, 20–120 days per participant), where Gemini 2.5 Pro reaches <strong>71.8%</strong> macro-average against a corrected human baseline of <strong>94.2%</strong>, and several models fall to or below the 25% random level on route reasoning and cross-view spatial reasoning (<a href="https://arxiv.org/abs/2608.13113" target="_blank" rel="noreferrer">arXiv:2608.13113</a>). Yet minimal pairs that differ <em>only</em> in temporal structure hold the best model to <strong>48.2% instance accuracy against 98.2% for humans</strong> (<a href="https://arxiv.org/abs/2602.00288" target="_blank" rel="noreferrer">arXiv:2602.00288</a>).</p><p><strong>More frames can raise the score without recovering the events.</strong> Under controlled rendering with executable ground-truth event traces, raising the sampling rate lifts accuracy from <strong>19.6% to 29.3%</strong>, while the share of reported sequences matching ground truth is <strong>3.7%</strong> (<a href="https://arxiv.org/abs/2608.06361" target="_blank" rel="noreferrer">arXiv:2608.06361</a>).</p><p><strong>Frame selection buys less than it appears to.</strong> The only paper in this window that states its absolute gain over uniform sampling reports <strong>+3.77 percentage points</strong> across four benchmarks and six frame budgets (<a href="https://arxiv.org/abs/2608.05707" target="_blank" rel="noreferrer">arXiv:2608.05707</a>); a companion result shows uniform sampling is both effective and efficient for <em>global</em> queries, so a method&#39;s average gain largely reflects the query-type mix of its chosen benchmarks (<a href="https://arxiv.org/abs/2512.04000" target="_blank" rel="noreferrer">arXiv:2512.04000</a>).</p><p><strong>Chain-of-thought often costs accuracy on open video models.</strong> Direct answer → CoT on Qwen2.5-VL-3B: MVBench 62.8 → 57.4, VideoMMMU 41.7 → 33.8, VSI-Bench 30.1 → 25.4. The same phenomenon reverses on GPT-4o (VSI-Bench 27.8 → 45.3) (<a href="https://arxiv.org/abs/2510.06077" target="_blank" rel="noreferrer">arXiv:2510.06077</a>).</p><p><strong>A training-free method comes within 0.6% of RL.</strong> Adjusting the value cache at inference time using an entropy objective closes the gap to RL-trained models to <strong>0.6% on average while using 58.6% fewer tokens</strong> (<a href="https://arxiv.org/abs/2510.17045" target="_blank" rel="noreferrer">arXiv:2510.17045</a>).</p><p><strong>Learned reward models for video are not yet usable.</strong> Across 28 multimodal reward models, the strongest (GPT-4o) reaches <strong>57.0%</strong> overall and the strongest open model <strong>53.3%</strong> (<a href="https://arxiv.org/abs/2509.00484" target="_blank" rel="noreferrer">arXiv:2509.00484</a>); a separate study finds learned multimodal reward models fail catastrophically and induce degenerate solutions, while verifiable task-metric rewards improve exact match by <strong>29.1% over an SFT baseline</strong> (<a href="https://arxiv.org/abs/2603.27866" target="_blank" rel="noreferrer">arXiv:2603.27866</a>).</p><p><strong>Synthetic data works, but only for programmatically verifiable primitives.</strong> 7.7K synthetic CoT samples beat Video-R1&#39;s 165K real samples (<a href="https://arxiv.org/abs/2603.17693" target="_blank" rel="noreferrer">arXiv:2603.17693</a>); 25K simulated examples let a 7B model beat a 72B baseline, and <em>fewer</em> question types beat comprehensive coverage (<a href="https://arxiv.org/abs/2511.04668" target="_blank" rel="noreferrer">arXiv:2511.04668</a>).</p><p><strong>The projector, not the encoder, is where temporal information dies.</strong> A frozen video-centric encoder probes at <strong>81.1%</strong> on Arrow-of-Time, but drops to <strong>50.0%</strong> once passed through a standard Q-Former-based Video-LLM. Replacing it with a time-preserving MLP recovers <strong>95.1%</strong> at 1024 tokens and <strong>92.0%</strong> at 256, where a time-compressed MLP gives 78.8% and a Q-Former stays at chance (<a href="https://arxiv.org/abs/2605.07568" target="_blank" rel="noreferrer">arXiv:2605.07568</a>).</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chapter</th><th>Contents</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>How to use this tutorial; reading paths; scope and information discipline</td></tr><tr><td><strong>1</strong></td><td>Concepts and intuition: the four qualitative changes the time axis introduces; three generations of paradigms; a map of the six research lines</td></tr><tr><td><strong>2</strong></td><td>Principles: the four layers from pixels to tokens; four spatio-temporal operators; masked reconstruction vs latent prediction (JEPA); video-language contrastive learning; how visual tokens enter the LLM; positional encoding and the time axis; the frame-budget trade-off; long context, KV cache and memory; SFT / RLVR / distillation; <strong>and the trivial-baseline checklist that runs through the whole tutorial</strong></td></tr><tr><td><strong>3</strong></td><td>Tasks: recognition, captioning, QA, grounding, retrieval, streaming, reasoning — inputs, outputs, metrics, current state</td></tr><tr><td><strong>4</strong></td><td>Benchmarks and evaluation, including the six audit papers that matter most and a table of known metric defects</td></tr><tr><td><strong>5</strong></td><td>Data: pre-training corpora, instruction and CoT synthesis, dense annotation, synthetic data and its marginal return, data selection, contamination and licensing</td></tr><tr><td><strong>6</strong></td><td>Methods I: visual backbones and representations; general Video-LLMs; long video (selection / retrieval / memory / agents)</td></tr><tr><td><strong>7</strong></td><td>Methods II: streaming and real-time; efficiency; reasoning and RL post-training; fine-grained specialised tasks</td></tr><tr><td><strong>8</strong></td><td>Six conclusions the evidence supports, five open problems, three emerging trends, six research gaps</td></tr><tr><td><strong>9</strong></td><td>Paper list (394 entries, grouped by theme)</td></tr><tr><td><strong>10</strong></td><td><strong>Per-paper explanations for all 394 papers</strong>: 14 full-text deep dives in an eight-question format, 380 abstract-based four-field entries</td></tr><tr><td><strong>Appendices</strong></td><td>Glossary · a four-week study plan · an experiment and paper self-check list</td></tr></tbody></table><h2 id="two-conventions-worth-copying" tabindex="-1">Two conventions worth copying <a class="header-anchor" href="#two-conventions-worth-copying" aria-label="Permalink to &quot;Two conventions worth copying&quot;">​</a></h2><p><strong>Every paper mention is a jump link.</strong> The tutorial contains <strong>394 anchors and 905 in-text jump links</strong>, script-verified to have zero dangling targets. Clicking any arXiv number in the body jumps to that paper&#39;s entry in Chapter 10.</p><p><strong>Evidence strength is labelled, not blurred.</strong> Chapter 10 separates 14 papers read in full text from 380 read at abstract level, and says so at the top of each section. Where an abstract contains no numbers at all — <strong>91 of the 380</strong> — the entry says so explicitly rather than paraphrasing around the gap.</p><h2 id="four-cross-cutting-statistics" tabindex="-1">Four cross-cutting statistics <a class="header-anchor" href="#four-cross-cutting-statistics" aria-label="Permalink to &quot;Four cross-cutting statistics&quot;">​</a></h2><p>Produced while reading all 380 abstracts; they quantify claims the earlier chapters could otherwise only assert.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Count</th></tr></thead><tbody><tr><td>General Video-LLM / omni technical reports whose <strong>abstract contains no video benchmark number at all</strong></td><td><strong>22 / 28</strong></td></tr><tr><td>Streaming papers that <strong>report an efficiency number without naming the hardware</strong></td><td><strong>10 / 12</strong> (16 more report no efficiency number)</td></tr><tr><td>Frame-selection papers that state an <strong>absolute gain over uniform sampling</strong></td><td><strong>4 / 49</strong></td></tr><tr><td>Efficiency papers that actually compare against <strong>random token pruning</strong></td><td><strong>4 / 34</strong></td></tr></tbody></table>',31)])])}const u=e(o,[["render",s]]);export{p as __pageData,u as default};
